bad_example:
-- construida dinamicamente a partir de filtros opcionales, ninguno provisto:
DELETE FROM sesiones;
-- borra la tabla COMPLETA, no solo las sesiones esperadas

BEGIN;
SELECT saldo FROM cuentas WHERE id = 1; -- lee 100
-- ... logica de negocio que asume que 100 sigue siendo verdad ...
UPDATE cuentas SET saldo = saldo - 50 WHERE id = 1; -- otra transaccion pudo haber cambiado el saldo entre medio
COMMIT;

good_example:
BEGIN;
SELECT saldo FROM cuentas WHERE id = 1 FOR UPDATE; -- lockea la fila, otras transacciones esperan
UPDATE cuentas SET saldo = saldo - 50 WHERE id = 1;
COMMIT;

SELECT * FROM (
  SELECT precio * cantidad AS total FROM pedidos
) sub WHERE total > 100; -- aca 'total' ya es una columna real de la subconsulta externa
